// Auth + validation. Deux kinds :
//   kind='post' : un workflow appelle pour écrire un message. body: { from_workflow, to_workflow, level, title, body?, item_type?, item_id?, escalated_to_human?, trace_id? }
//   kind='ack'  : un humain (ou un autre WF) marque un message comme pris en compte. body: { id, acknowledged_by, acknowledged_by_id }
const h = $json.headers || {};
const token = h['x-symbalyx-token'] || h['X-Symbalyx-Token'] || '';
const expected = $env.SYMBALYX_WEBHOOK_SECRET || '';
if (!expected) return [{ json: { _ok:false, _status:500, _error:'SYMBALYX_WEBHOOK_SECRET not configured' } }];
if (token !== expected) return [{ json: { _ok:false, _status:401, _error:'invalid_token' } }];

const b = $json.body || {};
const kind = String(b.kind || 'post').trim().toLowerCase();

if (kind === 'ack') {
  const id = String(b.id || '').trim();
  if (!id) return [{ json: { _ok:false, _status:400, _error:'missing id' } }];
  return [{ json: {
    _ok: true, kind: 'ack', id,
    acknowledged_by: String(b.acknowledged_by || ''),
    acknowledged_by_id: String(b.acknowledged_by_id || ''),
    acknowledged_at: new Date().toISOString()
  } }];
}

// kind = post
const LEVELS = ['info','progress','blocked'];
const level = String(b.level || 'info').toLowerCase();
if (!LEVELS.includes(level)) return [{ json: { _ok:false, _status:400, _error:'invalid level' } }];
const from_workflow = String(b.from_workflow || '').trim();
if (!from_workflow) return [{ json: { _ok:false, _status:400, _error:'missing from_workflow' } }];
const title = String(b.title || '').trim();
if (!title) return [{ json: { _ok:false, _status:400, _error:'missing title' } }];
if (title.length > 200) return [{ json: { _ok:false, _status:400, _error:'title too long (max 200)' } }];
const body = String(b.body || '');
if (body.length > 2000) return [{ json: { _ok:false, _status:400, _error:'body too long (max 2000)' } }];

const escalate = level === 'blocked' || String(b.escalated_to_human || '').toLowerCase() === 'true';

return [{ json: {
  _ok: true, kind: 'post',
  row: {
    id: 'agt_' + Date.now() + '_' + Math.random().toString(36).slice(2,7),
    ts: new Date().toISOString(),
    from_workflow,
    to_workflow: String(b.to_workflow || (escalate ? 'human' : '')),
    level,
    title,
    body,
    item_type: String(b.item_type || ''),
    item_id: String(b.item_id || ''),
    escalated_to_human: escalate ? 'true' : 'false',
    acknowledged_by: '',
    acknowledged_at: '',
    trace_id: String(b.trace_id || '')
  }
} }];

// Merge ack metadata sur la ligne ciblée.
const inp = $('Auth & validate').first().json;
const rows = $input.all().map(i => i.json);
const row = rows.find(r => String(r.id) === String(inp.id));
if (!row) return [{ json: { _ok:false, _status:404, _error:'agent_message not found' } }];
const merged = {
  id: row.id,
  ts: row.ts || '',
  from_workflow: row.from_workflow || '',
  to_workflow: row.to_workflow || '',
  level: row.level || 'info',
  title: row.title || '',
  body: row.body || '',
  item_type: row.item_type || '',
  item_id: row.item_id || '',
  escalated_to_human: row.escalated_to_human || 'false',
  acknowledged_by: inp.acknowledged_by || '',
  acknowledged_at: inp.acknowledged_at || '',
  trace_id: row.trace_id || ''
};
return [{ json: { _ok:true, merged } }];
